  function dayOf(q,def){const W={luni:1,marti:2,miercuri:3,joi:4,vineri:5};for(const k in W){if(new RegExp('\\b'+k+'\\b').test(q)){const d=new Date(today);do{d.setDate(d.getDate()+1);}while(d.getDay()!==W[k]);return d;}}if(/poimaine/.test(q))return addDays(today,2);if(/maine/.test(q))return addDays(today,1);if(/\b(azi|astazi)\b/.test(q))return new Date(today);return def;}
  function nextWork(d){d=new Date(d);while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1);return d;}
  function hourOf(q){const m=q.match(/(?:la|ora|de la|incepand cu)\s*(\d{1,2})(?:[:. ](\d{2}))?/);if(!m)return null;let h=+m[1],mi=m[2]&&+m[2]<60?+m[2]:0;mi=Math.round(mi/15)*15;if(mi===60){h++;mi=0;}return h*60+mi;}
  const hm=x=>String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');
  const SLOTS=(()=>{const a=[];for(let t=360;t<=1320;t+=15)a.push(hm(t));return a;})();
